class Solution {
public:
    long long countSubmatrices(vector<vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> width(m, vector<int>(n, 0));
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] > k) continue;
                width[i][j] = 1;
                if (j > 0 && grid[i][j - 1] >= grid[i][j]) width[i][j] += width[i][j - 1];
            }
        }
        long long ans = 0;
        for (int j = 0; j < n; ++j) {
            vector<pair<int, int>> stack;
            long long sum = 0;
            for (int i = 0; i < m; ++i) {
                int w = width[i][j], count = 1;
                while (!stack.empty() && stack.back().first >= w) {
                    sum -= 1LL * stack.back().first * stack.back().second;
                    count += stack.back().second;
                    stack.pop_back();
                }
                stack.push_back({w, count});
                sum += 1LL * w * count;
                ans += sum;
            }
        }
        return ans;
    }
};
